def toil_report(tasks, cap_fraction=0.5):
    if not tasks:
        return {"toil_percentage": 0, "breached": False}
    total_hours = sum(t["hours"] for t in tasks)
    toil_hours = sum(t["hours"] for t in tasks if t["is_toil"])
    toil_fraction = toil_hours / total_hours
    return {
        "toil_percentage": round(toil_fraction * 100, 1),
        "breached": toil_fraction > cap_fraction,
    }

print(toil_report(tasks))
